import * as THREE from "three";

/** The surface maps the renderer can wear. They are generated by
 * `pnpm assets:textures` and served from `public/art`. */
export interface ArtTextures {
  concrete: THREE.Texture | null;
  asphalt: THREE.Texture | null;
  grass: THREE.Texture | null;
  rust: THREE.Texture | null;
  /** Flipbook of the impact burst, packed by `tools/make-spark-atlas.ts`. */
  spark_atlas: THREE.Texture | null;
  /** Muzzle flash strip, packed by `tools/make-flipbook-atlas.ts`. */
  muzzle_atlas: THREE.Texture | null;
  /** Infected strike strip, packed by `tools/make-flipbook-atlas.ts`. */
  melee_atlas: THREE.Texture | null;
  /** Gunfire noise ring sheet, packed by `tools/make-flipbook-atlas.ts`. */
  noise_atlas: THREE.Texture | null;
  /** Death cloud sheet, packed by `tools/make-flipbook-atlas.ts`. */
  death_atlas: THREE.Texture | null;
  /** Construction dust sheet, packed by `tools/make-flipbook-atlas.ts`. */
  dust_atlas: THREE.Texture | null;
}

export type ArtName = keyof ArtTextures;

const NAMES: ArtName[] = [
  "concrete",
  "asphalt",
  "grass",
  "rust",
  "spark_atlas",
  "muzzle_atlas",
  "melee_atlas",
  "noise_atlas",
  "death_atlas",
  "dust_atlas",
];

/**
 * Loads the surface maps without blocking the first frame: the materials are
 * built with flat colours and gain their map as each file arrives. A missing
 * file keeps the flat colour, so art is never a hard dependency of booting.
 */
export function loadArtTextures(baseUrl: string, onReady: (art: ArtTextures) => void): ArtTextures {
  const art: ArtTextures = {
    concrete: null,
    asphalt: null,
    grass: null,
    rust: null,
    spark_atlas: null,
    muzzle_atlas: null,
    melee_atlas: null,
    noise_atlas: null,
    death_atlas: null,
    dust_atlas: null,
  };
  const loader = new THREE.TextureLoader();
  for (const name of NAMES) {
    loader.load(
      `${baseUrl}art/${name}.png`,
      (tex) => {
        tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
        tex.colorSpace = THREE.SRGBColorSpace;
        tex.anisotropy = 4;
        tex.needsUpdate = true;
        art[name] = tex;
        onReady(art);
      },
      undefined,
      () => {
        art[name] = null;
      },
    );
  }
  return art;
}
